package ai.decisionos.aside;
import android.content.*;import android.os.*;import android.view.*;import org.json.*;import java.util.concurrent.*;
final class TossHomeChecks {
 static String js(GoalInstrumentation i,NubiTossHomeUi home,String code)throws Exception{CountDownLatch latch=new CountDownLatch(1);String[] r={""};i.runOnMainSync(()->home.web.evaluateJavascript(code,v->{r[0]=v;latch.countDown();}));if(!latch.await(25,TimeUnit.SECONDS))throw new AssertionError("JS timeout: "+code);return r[0];}
 static void waitReady(GoalInstrumentation i,NubiTossHomeUi h)throws Exception{for(int n=0;n<50;n++){if("true".equals(js(i,h,"Boolean(window.NubiUI&&window.NubiUI.state.hydrated&&document.querySelectorAll('.agent').length===6)")))return;Thread.sleep(100);}throw new AssertionError("home ready");}
 static void run(GoalInstrumentation i){Bundle out=new Bundle();GoalAgentActivity a=null;try{
 a=(GoalAgentActivity)i.startActivitySync(new Intent(i.getTargetContext(),GoalAgentActivity.class).putExtra("companion_page","홈").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final GoalAgentActivity h=a;NubiCompanionUi u=h.chat.companion;i.waitForIdleSync();NubiTossHomeUi home=u.tossHome;i.check(home!=null,"new home mounted");waitReady(i,home);boolean[] safe={false};i.runOnMainSync(()->safe[0]=!home.web.getSettings().getAllowFileAccess()&&home.web.getSettings().getBlockNetworkLoads());i.check(safe[0],"local only blocked network");
 for(String v:new String[]{"A1","A2","A3","A4","A5","D1","D2","D3","D4","D5"}){
  js(i,home,"NubiUI.action('variant:"+v+"')");Thread.sleep(300);i.check("true".equals(js(i,home,"NubiUI.state.variant==='"+v+"'")),v+" selected");i.check("6".equals(js(i,home,"document.querySelectorAll('.agent').length")),v+" six agents");i.check("true".equals(js(i,home,"document.documentElement.scrollWidth<=innerWidth+1")),v+" no horizontal overflow");i.check("true".equals(js(i,home,"Boolean(document.querySelector('.hero,.split-story'))")),v+" primary suggestion");
  js(i,home,"NubiUI.action('detail:route')");Thread.sleep(350);i.check("true".equals(js(i,home,"document.querySelector('[role=dialog]').innerText.includes('UNIST')")),v+" detail opened");js(i,home,"NubiUI.close()");Thread.sleep(300);i.check("0".equals(js(i,home,"document.querySelectorAll('.layer').length")),v+" detail closed");
  if(i.scenario.containsKey("captureStudies"))HomeUiChecks.shot(i,"study-"+v+".png");
 }
 for(String scene:new String[]{"morning","lunch","travel","school","night","invest","now"}){js(i,home,"NubiUI.action('scenario:"+scene+"')");i.check("true".equals(js(i,home,"NubiUI.state.scenario==='"+scene+"'")),"scenario "+scene);}
 for(GoalRules.Preset p:GoalRules.PRESETS){final String id=p.id;final NubiTossHomeUi before=h.chat.companion.tossHome;i.runOnMainSync(()->before.new Bridge().chat(id,p.name+" 홈 동작 검증 요청"));i.waitForIdleSync();i.check(h.chat.character.equals(id),"correct agent "+id);i.check(h.chat.companion.page.equals("대화"),"native chat "+id);String[] draft={""};i.runOnMainSync(()->draft[0]=h.chat.input.getText().toString());i.check(!draft[0].isBlank(),"draft "+id);i.check(!h.chat.running&&!h.chat.submitting,"no autosubmit "+id);i.runOnMainSync(()->h.chat.companion.select("홈"));waitReady(i,h.chat.companion.tossHome);}
 final NubiCompanionUi current=h.chat.companion;final NubiTossHomeUi currentHome=current.tossHome;
 i.runOnMainSync(()->currentHome.new Bridge().route("수집 설정"));i.waitForIdleSync();i.check(current.page.equals("홈"),"bridge rejects nonallowlisted routes");i.runOnMainSync(()->currentHome.new Bridge().chat("invalid","x"));i.waitForIdleSync();i.check(current.page.equals("홈"),"bridge rejects invalid agent");
 for(String p:new String[]{"친구","탐색","작업","내 정보"}){i.runOnMainSync(()->currentHome.new Bridge().route(p));i.waitForIdleSync();i.check(current.page.equals(p),"existing page "+p);i.check(((View)current.globalTitle.getParent()).getVisibility()==View.VISIBLE,"existing header restored "+p);i.runOnMainSync(()->current.select("홈"));waitReady(i,currentHome);}
 i.runOnMainSync(()->{h.getSharedPreferences("home_studies",0).edit().putString("variant",BuildConfig.HOME_STYLE==4?"D1":"A1").putString("scenario","now").apply();currentHome.sync();});i.waitForIdleSync();HomeUiChecks.shot(i,"study-final-home.png");
 out.putString("stream","PASS "+i.checks+" A/D home study checks\n");
 }catch(Throwable e){out.putString("stream","FAIL "+e+"\n");}finally{if(a!=null){GoalAgentActivity h=a;i.runOnMainSync(h::finish);}}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}
}
